import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildTelegramReportText } from "./_shared/reportText.ts";
import { renderTelegramReportPng } from "./_shared/renderReportPng.ts";
import type { ReportManagerRow, TelegramReportPayload } from "./_shared/telegramReportTypes.ts";

/** Дата календаря в указанном IANA TZ → YYYY-MM-DD */
function dateYmdInTz(d: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(d);
  const byType = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${byType.year}-${byType.month}-${byType.day}`;
}

function formatDateDisplay(ymd: string): string {
  const m = ymd.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return ymd;
  return `${m[3]}-${m[2]}-${m[1]}`;
}

function errText(e: unknown): string {
  if (e instanceof Error) return `${e.name}: ${e.message}`;
  try {
    return JSON.stringify(e);
  } catch {
    return String(e);
  }
}

const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-cron-key",
};

function isYmd(s: string): boolean {
  return /^\d{4}-\d{2}-\d{2}$/.test(s);
}

function reportAsImageEnabled(): boolean {
  const raw = (Deno.env.get("TELEGRAM_REPORT_AS_IMAGE") ?? "true").trim().toLowerCase();
  return raw !== "0" && raw !== "false" && raw !== "no";
}

async function sendTelegramMessage(botToken: string, chatId: string, text: string): Promise<void> {
  const tgRes = await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      chat_id: chatId,
      text,
      parse_mode: "HTML",
      disable_web_page_preview: true,
    }),
  });
  const tg = await tgRes.json();
  if (!tg?.ok) throw new Error(`telegram sendMessage failed: ${JSON.stringify(tg)}`);
}

async function sendTelegramPhoto(
  botToken: string,
  chatId: string,
  png: Uint8Array,
  caption?: string,
): Promise<void> {
  const form = new FormData();
  form.append("chat_id", chatId);
  form.append("photo", new Blob([png], { type: "image/png" }), "crm-report.png");
  if (caption) form.append("caption", caption);
  const tgRes = await fetch(`https://api.telegram.org/bot${botToken}/sendPhoto`, {
    method: "POST",
    body: form,
  });
  const tg = await tgRes.json();
  if (!tg?.ok) throw new Error(`telegram sendPhoto failed: ${JSON.stringify(tg)}`);
}

/** Cron (`x-cron-key`) или JWT администратора. */
async function isRequestAuthorized(req: Request): Promise<boolean> {
  const cronKey = Deno.env.get("TELEGRAM_CRON_SECRET") ?? "";
  if (cronKey && (req.headers.get("x-cron-key") ?? "") === cronKey) return true;

  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return false;

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const anon = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
  if (!supabaseUrl || !anon) return false;

  const userClient = createClient(supabaseUrl, anon, {
    global: { headers: { Authorization: authHeader } },
  });
  const { data: { user } } = await userClient.auth.getUser();
  if (!user) return false;

  const { data: prof } = await userClient.from("profiles").select("role, admin_write").eq("id", user.id).maybeSingle();
  return prof?.role === "admin" && prof?.admin_write !== false;
}

async function loadReportPayload(
  supabase: ReturnType<typeof createClient>,
  reportDate: string,
  tz: string,
  reportDateLabel: string,
): Promise<TelegramReportPayload> {
  const [
    { data, error },
    { data: forecastData, error: forecastError },
    { data: totalsData, error: totalsError },
  ] = await Promise.all([
    supabase.rpc("telegram_daily_analytics_rows", { p_date: reportDate }),
    supabase.rpc("get_crm_telegram_weekly_forecast"),
    supabase.rpc("telegram_confirmed_orders_totals", { p_tz: tz, p_date: reportDate }),
  ]);
  if (error) throw error;
  if (forecastError) throw forecastError;
  if (totalsError) throw totalsError;

  const rows = (data ?? []) as ReportManagerRow[];
  const weeklyForecast = Number(forecastData ?? 0);
  const totalsRow = (Array.isArray(totalsData) ? totalsData[0] : totalsData) as
    | { today_sum?: number; week_sum?: number }
    | null
    | undefined;
  const todayOrdersSum = Number(totalsRow?.today_sum ?? 0);
  const weekOrdersSum = Number(totalsRow?.week_sum ?? 0);

  const total = rows.reduce(
    (acc, r) => ({
      assigned: acc.assigned + Number(r.assigned_meetings ?? 0),
      conductedFact: acc.conductedFact + Number(r.conducted_fact ?? 0),
      ordersSum: acc.ordersSum + Number(r.confirmed_orders_sum ?? 0),
      ordersCount: acc.ordersCount + Number(r.confirmed_orders_count ?? 0),
    }),
    { assigned: 0, conductedFact: 0, ordersSum: 0, ordersCount: 0 },
  );

  return {
    reportDateLabel,
    weeklyForecast,
    todayOrdersSum,
    weekOrdersSum,
    total,
    rows,
  };
}

export async function handleCronReport(req: Request): Promise<Response> {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    if (!(await isRequestAuthorized(req))) {
      return new Response(JSON.stringify({ ok: false, error: "forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const url = new URL(req.url);
    const previewPng = url.searchParams.get("preview") === "png";

    const botToken = Deno.env.get("TELEGRAM_BOT_TOKEN") ?? "";
    const chatId = Deno.env.get("TELEGRAM_CHAT_ID") ?? "";
    if (!previewPng && (!botToken || !chatId)) {
      throw new Error("TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID missing");
    }

    const tz = Deno.env.get("REPORT_TIMEZONE") ?? "Asia/Almaty";
    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
    if (!supabaseUrl || !serviceKey) {
      throw new Error("SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY missing");
    }

    const supabase = createClient(supabaseUrl, serviceKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    let reportDate = dateYmdInTz(new Date(), tz);
    const urlDate = (url.searchParams.get("report_date") ?? url.searchParams.get("p_date") ?? "").trim();
    if (urlDate && isYmd(urlDate)) reportDate = urlDate;
    try {
      const ct = (req.headers.get("content-type") ?? "").toLowerCase();
      if (ct.includes("application/json")) {
        const j = (await req.json()) as { report_date?: string; p_date?: string; preview?: boolean };
        const raw = (j.report_date ?? j.p_date ?? "").trim();
        if (raw && isYmd(raw)) reportDate = raw;
      }
    } catch {
      /* пустое тело — отчёт за сегодня */
    }
    const reportDateLabel = formatDateDisplay(reportDate);
    const payload = await loadReportPayload(supabase, reportDate, tz, reportDateLabel);
    const text = buildTelegramReportText(payload);
    const caption = `Сводка за ${reportDateLabel}`;

    if (previewPng) {
      const png = await renderTelegramReportPng(payload);
      return new Response(png, {
        headers: {
          ...corsHeaders,
          "Content-Type": "image/png",
          "Cache-Control": "no-store",
        },
      });
    }

    let delivery: "photo" | "text" = "text";
    let imageError: string | undefined;
    if (reportAsImageEnabled()) {
      try {
        const png = await renderTelegramReportPng(payload);
        await sendTelegramPhoto(botToken, chatId, png, caption);
        delivery = "photo";
      } catch (imgErr) {
        imageError = errText(imgErr);
        console.error("[telegram-daily-report] image failed, fallback to text:", imageError);
        await sendTelegramMessage(botToken, chatId, text);
        delivery = "text";
      }
    } else {
      await sendTelegramMessage(botToken, chatId, text);
    }

    return new Response(
      JSON.stringify({
        ok: true,
        reportDate,
        reportDateLabel,
        chatId,
        managers: payload.rows.length,
        delivery,
        imageError,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (e) {
    return new Response(JSON.stringify({ ok: false, error: errText(e) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
}

export type ReportOrderBreakdown = {
  name?: string;
  bin?: string;
  total?: number;
  order_count?: number;
};

export type ReportManagerRow = {
  manager: string;
  assigned_meetings: number;
  conducted_fact: number;
  conducted_new?: number;
  confirmed_orders_sum: number;
  confirmed_orders_count: number;
  confirmed_orders_breakdown: ReportOrderBreakdown[] | null;
};

export type TelegramReportTotals = {
  assigned: number;
  conductedFact: number;
  ordersSum: number;
  ordersCount: number;
};

export type TelegramReportPayload = {
  reportDateLabel: string;
  weeklyForecast: number;
  todayOrdersSum: number;
  weekOrdersSum: number;
  total: TelegramReportTotals;
  rows: ReportManagerRow[];
};

import type { ReportManagerRow, TelegramReportPayload } from "./telegramReportTypes.ts";

export function escHtml(s: string): string {
  return s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}

export function money(n: number): string {
  return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 0 }).format(Number.isFinite(n) ? n : 0);
}

export function parseBreakdown(raw: unknown): ReportManagerRow["confirmed_orders_breakdown"] {
  if (raw == null) return [];
  if (Array.isArray(raw)) return raw as ReportManagerRow["confirmed_orders_breakdown"];
  return [];
}

export function buildTelegramReportText(payload: TelegramReportPayload): string {
  const { reportDateLabel, weeklyForecast, todayOrdersSum, weekOrdersSum, total, rows } = payload;
  const lines: string[] = [];

  lines.push(`📊 <b>Сводка за ${escHtml(reportDateLabel)}</b>`);
  lines.push("━━━━━━━━━━━━━━━━━━━━");
  lines.push("");
  lines.push(`Прогноз на неделю: <b>${money(weeklyForecast)} ₸</b>`);
  lines.push(`Сумма заказов за день: <b>${money(todayOrdersSum)} ₸</b>`);
  lines.push(`Сумма заказов за неделю (в текущем месяце): <b>${money(weekOrdersSum)} ₸</b>`);
  lines.push("");
  lines.push("<b>Общая сводка</b>");
  lines.push(`• Назначено встреч: <b>${total.assigned}</b>`);
  lines.push(`• Факт проведено: <b>${total.conductedFact}</b>`);
  lines.push(`• Подтверждённых заказов: <b>${total.ordersCount}</b> на <b>${money(total.ordersSum)} ₸</b>`);
  lines.push("");
  lines.push("<b>По менеджерам</b>");

  const sorted = [...rows].sort((a, b) => (a.manager ?? "").localeCompare(b.manager ?? "", "ru"));

  if (sorted.length === 0) {
    lines.push("• Нет отчётов за день");
  } else {
    for (const r of sorted) {
      const name = escHtml((r.manager ?? "").trim() || "Без имени");
      lines.push("");
      lines.push(`<b>${name}</b>`);
      lines.push(`  Назначено встреч: <b>${r.assigned_meetings ?? 0}</b>`);
      lines.push(`  Факт проведено: <b>${r.conducted_fact ?? 0}</b>`);
      const mgrOrdersCount = Number(r.confirmed_orders_count ?? 0);
      lines.push(
        `  Подтверждённых заказов: <b>${mgrOrdersCount}</b> на <b>${money(Number(r.confirmed_orders_sum ?? 0))} ₸</b>`,
      );
      const br = parseBreakdown(r.confirmed_orders_breakdown);
      if (br.length === 0) {
        lines.push("  Заказы: нет");
      } else {
        lines.push("  Подтверждённые заказы:");
        for (const o of br) {
          const rawName = (o?.name ?? "").trim();
          const label = rawName ? escHtml(rawName) : `БИН ${escHtml(String((o?.bin ?? "").trim()))}`;
          const cnt = Number(o?.order_count ?? 0);
          lines.push(`   — ${label}: <b>${money(Number(o?.total ?? 0))} ₸</b> · <b>${cnt}</b> зак.`);
        }
      }
    }
  }

  return lines.join("\n");
}

import React from "https://esm.sh/react@18.3.1";
import type { CSSProperties, ReactElement } from "https://esm.sh/react@18.3.1";
import type { ReportManagerRow, TelegramReportPayload } from "./telegramReportTypes.ts";
import { money, parseBreakdown } from "./reportText.ts";

const WIDTH = 1080;

const c = {
  page: "#f8fafc",
  white: "#ffffff",
  border: "#f1f5f9",
  borderBlue: "#dbeafe",
  text: "#1e293b",
  textDark: "#0f172a",
  muted: "#94a3b8",
  muted2: "#64748b",
  blue: "#2563eb",
  blueSoft: "#eff6ff",
  blueDot: "#60a5fa",
  chipBg: "#f1f5f9",
};

type Style = CSSProperties;

function box(style: Style, ...children: React.ReactNode[]): ReactElement {
  return React.createElement("div", { style }, ...children);
}

function text(value: string, style: Style): ReactElement {
  return React.createElement("div", { style }, value);
}

function kpiCard(label: string, value: string, valueColor: string): ReactElement {
  return box(
    {
      display: "flex",
      flexDirection: "column",
      flex: 1,
      backgroundColor: c.white,
      padding: "20px 22px",
      borderRadius: 16,
      border: `1px solid ${c.border}`,
    },
    text(label, {
      fontSize: 13,
      fontWeight: 600,
      color: c.muted,
      textTransform: "uppercase",
      letterSpacing: 1.2,
      marginBottom: 10,
    }),
    text(value, {
      fontSize: 28,
      fontWeight: 800,
      color: valueColor,
    }),
  );
}

function managerCard(r: ReportManagerRow): ReactElement {
  const name = (r.manager ?? "").trim() || "Без имени";
  const assigned = Number(r.assigned_meetings ?? 0);
  const conducted = Number(r.conducted_fact ?? 0);
  const ordersCount = Number(r.confirmed_orders_count ?? 0);
  const ordersSum = Number(r.confirmed_orders_sum ?? 0);
  const br = parseBreakdown(r.confirmed_orders_breakdown) ?? [];
  const hasOrders = br.length > 0;
  const sumColor = ordersSum > 0 ? c.blue : c.textDark;

  const body = !hasOrders
    ? box(
      {
        display: "flex",
        flexDirection: "column",
        padding: "18px 22px",
      },
      text("Заказы отсутствуют", {
        fontSize: 16,
        color: c.muted,
        fontStyle: "italic",
      }),
    )
    : box(
      {
        display: "flex",
        flexDirection: "column",
        padding: "18px 22px",
        width: "100%",
      },
      text("Детализация", {
        fontSize: 12,
        fontWeight: 700,
        color: c.muted,
        textTransform: "uppercase",
        letterSpacing: 1.2,
        marginBottom: 14,
      }),
      ...br.map((o, idx) => {
        const rawName = (o?.name ?? "").trim();
        const label = rawName || `БИН ${(o?.bin ?? "").trim() || "—"}`;
        const cnt = Number(o?.order_count ?? 0);
        const isLast = idx === br.length - 1;
        return box(
          {
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "center",
            width: "100%",
            paddingBottom: isLast ? 0 : 12,
            marginBottom: isLast ? 0 : 12,
            borderBottom: isLast ? "none" : `1px solid ${c.border}`,
          },
          box(
            {
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              gap: 10,
              flex: 1,
            },
            box({
              width: 8,
              height: 8,
              borderRadius: 4,
              backgroundColor: c.blueDot,
            }),
            text(label, {
              fontSize: 16,
              fontWeight: 500,
              color: "#334155",
            }),
            box(
              {
                display: "flex",
                backgroundColor: c.chipBg,
                borderRadius: 6,
                padding: "2px 8px",
              },
              text(`${cnt} зак.`, {
                fontSize: 12,
                color: c.muted2,
              }),
            ),
          ),
          text(`${money(Number(o?.total ?? 0))} ₸`, {
            fontSize: 16,
            fontWeight: 700,
            color: c.textDark,
          }),
        );
      }),
    );

  return box(
    {
      display: "flex",
      flexDirection: "column",
      width: "100%",
      backgroundColor: c.white,
      borderRadius: 16,
      border: `1px solid ${c.border}`,
      overflow: "hidden",
    },
    box(
      {
        display: "flex",
        flexDirection: "row",
        justifyContent: "space-between",
        alignItems: "center",
        width: "100%",
        padding: "18px 22px",
        backgroundColor: "#f8fafc",
        borderBottom: `1px solid ${c.border}`,
      },
      text(name, {
        fontSize: 18,
        fontWeight: 600,
        color: c.textDark,
        width: 280,
      }),
      box(
        {
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          backgroundColor: "#f1f5f980",
          borderRadius: 8,
          padding: "6px 12px",
        },
        text(`Встречи: ${assigned} / ${conducted}`, {
          fontSize: 13,
          fontWeight: 500,
          color: c.muted2,
        }),
      ),
      text(`${ordersCount} на ${money(ordersSum)} ₸`, {
        fontSize: 17,
        fontWeight: 700,
        color: sumColor,
        textAlign: "right",
        width: 280,
      }),
    ),
    body,
  );
}

/** Точная оценка высоты под светлый макет — без лишнего белого низа. */
export function estimateReportHeight(payload: TelegramReportPayload): number {
  const sorted = [...payload.rows].sort((a, b) => (a.manager ?? "").localeCompare(b.manager ?? "", "ru"));

  // padding 32+40 + header ~100 + gap 24 + kpi ~100 + gap 24 + summary ~88 + gap 28 + title ~44
  let height = 32 + 40 + 100 + 24 + 100 + 24 + 88 + 28 + 44;

  if (sorted.length === 0) {
    height += 48;
  } else {
    for (let i = 0; i < sorted.length; i++) {
      const br = parseBreakdown(sorted[i].confirmed_orders_breakdown) ?? [];
      // header row ~64 + body
      let card = 64;
      if (br.length === 0) {
        card += 56; // italic empty
      } else {
        card += 18 + 14 + 18 + br.length * 44; // padding + label + rows
      }
      height += card;
      if (i < sorted.length - 1) height += 16; // gap
    }
  }

  return Math.max(700, Math.min(height + 8, 20000));
}

export function buildTelegramReportElement(payload: TelegramReportPayload): ReactElement {
  const { reportDateLabel, weeklyForecast, todayOrdersSum, weekOrdersSum, total, rows } = payload;
  const sorted = [...rows].sort((a, b) => (a.manager ?? "").localeCompare(b.manager ?? "", "ru"));

  const managersBlock = sorted.length === 0
    ? text("Нет отчётов за день", { fontSize: 16, color: c.muted, marginTop: 8 })
    : box(
      {
        display: "flex",
        flexDirection: "column",
        width: "100%",
        gap: 16,
      },
      ...sorted.map((r) => managerCard(r)),
    );

  return box(
    {
      display: "flex",
      flexDirection: "column",
      width: WIDTH,
      backgroundColor: c.page,
      padding: "32px 36px 40px",
      fontFamily: "Noto Sans",
      color: c.text,
    },
    // Header
    box(
      {
        display: "flex",
        flexDirection: "column",
        borderBottom: "1px solid #e2e8f0",
        paddingBottom: 18,
        marginBottom: 24,
      },
      text("Omarket Отдел Привлечения Крупного Бизнеса", {
        fontSize: 18,
        fontWeight: 700,
        color: c.blue,
        textTransform: "uppercase",
        letterSpacing: 1.5,
        marginBottom: 8,
      }),
      text(`Сводка за ${reportDateLabel}`, {
        fontSize: 30,
        fontWeight: 800,
        color: c.textDark,
      }),
    ),
    // KPI row
    box(
      {
        display: "flex",
        flexDirection: "row",
        gap: 16,
        width: "100%",
        marginBottom: 24,
      },
      kpiCard("Прогноз на неделю", `${money(weeklyForecast)} ₸`, c.blue),
      kpiCard("Заказы за день", `${money(todayOrdersSum)} ₸`, c.textDark),
      kpiCard("Заказы за неделю", `${money(weekOrdersSum)} ₸`, c.textDark),
    ),
    // General summary
    box(
      {
        display: "flex",
        flexDirection: "row",
        justifyContent: "space-between",
        alignItems: "center",
        width: "100%",
        backgroundImage: "linear-gradient(90deg, #eff6ff 0%, #ffffff 100%)",
        border: `1px solid ${c.borderBlue}`,
        borderRadius: 16,
        padding: "18px 22px",
        marginBottom: 28,
      },
      text("Общая сводка", {
        fontSize: 17,
        fontWeight: 700,
        color: c.text,
      }),
      box(
        {
          display: "flex",
          flexDirection: "row",
          gap: 12,
        },
        box(
          {
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            gap: 8,
            backgroundColor: c.white,
            borderRadius: 12,
            border: `1px solid ${c.blueSoft}`,
            padding: "8px 14px",
          },
          text("Встречи (назн./факт):", { fontSize: 14, color: c.muted2 }),
          text(`${total.assigned} / ${total.conductedFact}`, {
            fontSize: 14,
            fontWeight: 700,
            color: c.textDark,
          }),
        ),
        box(
          {
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            gap: 8,
            backgroundColor: c.white,
            borderRadius: 12,
            border: `1px solid ${c.blueSoft}`,
            padding: "8px 14px",
          },
          text("Заказы:", { fontSize: 14, color: c.muted2 }),
          text(`${total.ordersCount} на ${money(total.ordersSum)} ₸`, {
            fontSize: 14,
            fontWeight: 700,
            color: "#1d4ed8",
          }),
        ),
      ),
    ),
    // Managers
    box(
      {
        display: "flex",
        flexDirection: "column",
        width: "100%",
      },
      text("По менеджерам", {
        fontSize: 20,
        fontWeight: 700,
        color: c.text,
        marginBottom: 16,
        lineHeight: 1.3,
      }),
      managersBlock,
    ),
  );
}

export const REPORT_IMAGE_WIDTH = WIDTH;

import satori from "https://esm.sh/satori@0.12.2";
import { initWasm, Resvg } from "https://esm.sh/@resvg/resvg-wasm@2.6.2";
import type { TelegramReportPayload } from "./telegramReportTypes.ts";
import {
  buildTelegramReportElement,
  estimateReportHeight,
  REPORT_IMAGE_WIDTH,
} from "./telegramReportCard.ts";

const FONT_REGULAR_URL =
  "https://raw.githubusercontent.com/notofonts/noto-fonts/main/hinted/ttf/NotoSans/NotoSans-Regular.ttf";
const FONT_BOLD_URL =
  "https://raw.githubusercontent.com/notofonts/noto-fonts/main/hinted/ttf/NotoSans/NotoSans-Bold.ttf";

/** Фон страницы (slate-50) — по нему режем пустой низ. */
const PAGE_BG = { r: 0xf8, g: 0xfa, b: 0xfc };
const CROP_PAD = 28;

let wasmReady: Promise<void> | null = null;
let fontsReady: Promise<Array<{ name: string; data: ArrayBuffer; weight: number; style: "normal" }>> | null =
  null;

async function ensureWasm(): Promise<void> {
  if (!wasmReady) {
    wasmReady = (async () => {
      const wasmRes = await fetch("https://esm.sh/@resvg/resvg-wasm@2.6.2/index_bg.wasm");
      if (!wasmRes.ok) throw new Error(`resvg wasm fetch failed: ${wasmRes.status}`);
      await initWasm(await wasmRes.arrayBuffer());
    })();
  }
  await wasmReady;
}

async function loadFonts(): Promise<Array<{ name: string; data: ArrayBuffer; weight: number; style: "normal" }>> {
  if (!fontsReady) {
    fontsReady = (async () => {
      const [regularRes, boldRes] = await Promise.all([
        fetch(FONT_REGULAR_URL),
        fetch(FONT_BOLD_URL),
      ]);
      if (!regularRes.ok) throw new Error(`font regular fetch failed: ${regularRes.status}`);
      if (!boldRes.ok) throw new Error(`font bold fetch failed: ${boldRes.status}`);
      const [regular, bold] = await Promise.all([regularRes.arrayBuffer(), boldRes.arrayBuffer()]);
      return [
        { name: "Noto Sans", data: regular, weight: 400, style: "normal" as const },
        { name: "Noto Sans", data: bold, weight: 700, style: "normal" as const },
      ];
    })();
  }
  return fontsReady;
}

function isBgPixel(pixels: Uint8Array, offset: number): boolean {
  const r = pixels[offset];
  const g = pixels[offset + 1];
  const b = pixels[offset + 2];
  const a = pixels[offset + 3];
  if (a < 8) return true;
  return (
    Math.abs(r - PAGE_BG.r) <= 3 &&
    Math.abs(g - PAGE_BG.g) <= 3 &&
    Math.abs(b - PAGE_BG.b) <= 3
  );
}

function measureContentHeight(width: number, height: number, pixels: Uint8Array): number {
  for (let y = height - 1; y >= 0; y--) {
    const row = y * width * 4;
    for (let x = 0; x < width; x++) {
      if (!isBgPixel(pixels, row + x * 4)) {
        return Math.min(height, y + 1 + CROP_PAD);
      }
    }
  }
  return height;
}

async function svgToPng(svg: string): Promise<{ png: Uint8Array; width: number; height: number; pixels: Uint8Array }> {
  const resvg = new Resvg(svg, {
    fitTo: { mode: "width", value: REPORT_IMAGE_WIDTH },
  });
  const rendered = resvg.render();
  const width = rendered.width;
  const height = rendered.height;
  const pixels = new Uint8Array(rendered.pixels);
  const png = rendered.asPng();
  rendered.free();
  resvg.free();
  return { png, width, height, pixels };
}

export async function renderTelegramReportPng(payload: TelegramReportPayload): Promise<Uint8Array> {
  await ensureWasm();
  const fonts = await loadFonts();
  const element = buildTelegramReportElement(payload);

  // 1) черновик с запасом
  const draftH = estimateReportHeight(payload) + 120;
  const draftSvg = await satori(element, {
    width: REPORT_IMAGE_WIDTH,
    height: draftH,
    fonts,
  });
  const draft = await svgToPng(draftSvg);
  const contentH = measureContentHeight(draft.width, draft.height, draft.pixels);

  // 2) если низ пустой — перерендер ровно по контенту
  if (contentH < draft.height - 8) {
    const finalSvg = await satori(element, {
      width: REPORT_IMAGE_WIDTH,
      height: contentH,
      fonts,
    });
    const final = await svgToPng(finalSvg);
    return final.png;
  }

  return draft.png;
}
